<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap(); echo json_encode(\App\Models\MasterCourse::where(function($q) { $q->whereNull("user_id")->orWhereHas("user", function($u) { $u->where("role", "!=", "vendor"); }); })->get(["id", "name", "user_id"])->toArray(), JSON_PRETTY_PRINT);
